/// <summary>
/// Utility class for X++ interpreter execution
/// </summary>
internal final class MXTXppInterpreterExecutor
{
    private static XppInterpreter.Interpreter.Proxy.XppProxy proxy;

}

Method.Source:
/// <summary>
/// Static constructor
/// </summary>
static void TypeNew()
{
    proxy = new XppInterpreter.Interpreter.Proxy.XppProxy(
        new MXTXppIntrinsicFunctionProvider(),
        new MXTXppBinaryOperationProxy(),
        new MXTXppCastingProxy(),
        new MXTXppUnaryOperationProxy(),
        new MXTXppDataAccessProxy(),
        new MXTXppReflectionProxy(),
        new MXTXppExceptionsProxy(),
        new MXTXppQueryGenerationProxy());
}

/// <summary>
/// Encodes the given string into a base64 string
/// </summary>
/// <param name = "_sourceCode"></param>
/// <returns></returns>
public static str base64Encode(str _sourceCode)
{
    var plainTextBytes = System.Text.Encoding::UTF8.GetBytes(_sourceCode);
    return System.Convert::ToBase64String(plainTextBytes);
}

/// <summary>
/// Decodes the given base64 string
/// </summary>
/// <param name = "_base64SourceCode"></param>
/// <returns></returns>
public static str base64Decode(str _base64SourceCode)
{
    var base64EncodedBytes = System.Convert::FromBase64String(_base64SourceCode);
    return System.Text.Encoding::UTF8.GetString(base64EncodedBytes);
}

/// <summary>
/// Executes the given script with the specified parameters
/// </summary>
/// <param name = "_script">A record of <c>MXTXppInterpreterScript</c></param>
/// <param name = "_parameters">A record of <c>MXTXppInterpreterParameters</c></param>
public static void executeScript(MXTXppInterpreterScript _script, MXTXppInterpreterParameters _parameters)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();
    var dependencies = MXTXppScriptDependencyManager::parseDependencies(_script.RecId);

    MXTXppInterpreterExecutor::execute(_script.SourceCode, null, _parameters, dependencies);
}

/// <summary>
/// Creates a lexer with D365FO macro dictionary resolution enabled.
/// </summary>
public static XppInterpreter.Lexer.XppLexer createLexer(str _sourceCode)
{
    return new XppInterpreter.Lexer.XppLexer(_sourceCode, MXTXppInterpreterExecutor::createMacroPreprocessor());
}

/// <summary>
/// Creates a macro preprocessor that resolves D365FO macro dictionaries.
/// </summary>
public static XppInterpreter.Lexer.MacroPreprocessor createMacroPreprocessor()
{
    XppInterpreter.Lexer.MacroPreprocessor preprocessor = new XppInterpreter.Lexer.MacroPreprocessor();

    try
    {
        str packagesBinDirectory = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::PackagesBinDirectory;
        System.IO.DirectoryInfo packagesDirectory = System.IO.Directory::GetParent(packagesBinDirectory);

        if (packagesDirectory != null)
        {
            preprocessor.UseFileSystemMacroLibraries(packagesDirectory.FullName);
        }
    }
    catch (Exception::CLRError)
    {
        // The lexer reports a clear #macrolib resolution error when package
        // metadata isn't available in the current deployment topology.
    }

    return preprocessor;
}

/// <summary>
/// Parse the given source code into a program AST
/// </summary>
/// <param name = "_sourceCode">Source code</param>
/// <returns>Program AST</returns>
public static XppInterpreter.Parser.ParseResult parse(str _sourceCode)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();
    XppInterpreter.Lexer.XppLexer lexer = MXTXppInterpreterExecutor::createLexer(_sourceCode);
    XppInterpreter.Parser.XppParser parser = new XppInterpreter.Parser.XppParser(lexer, proxy);

    return parser.Parse();
}

/// <summary>
///     Executes the given source code expression with the specified runtime context
/// </summary>
/// <param name = "_sourceCode">Expression code</param>
/// <param name = "_context">Runtime context to give to the parser and interpreter</param>
/// <returns></returns>
public static anytype executeExpressionWithContext(str _sourceCode, XppInterpreter.Interpreter.RuntimeContext _context)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();
    XppInterpreter.Lexer.XppLexer lexer = MXTXppInterpreterExecutor::createLexer(_sourceCode);
    XppInterpreter.Parser.ParseContext parseContext = XppInterpreter.Parser.ParseContext::FromRuntimeContext(_context);
    var result = XppInterpreter.Parser.XppParser::ParseExpressionWithContext(lexer, proxy, parseContext);

    if (result.IsCorrect)
    {
        XppInterpreter.Parser.Expression expression = result.AST as XppInterpreter.Parser.Expression;

        // Generate bytecode
        XppInterpreter.Interpreter.Bytecode.ByteCodeGenerator generator = new XppInterpreter.Interpreter.Bytecode.ByteCodeGenerator();

        expression.Accept(generator);

        XppInterpreter.Interpreter.Bytecode.ByteCode byteCode = generator.GeneratedByteCode;
        MXTXppInterpreterParameters parameters = MXTXppInterpreterParameters::find();
        XppInterpreter.Interpreter.XppInterpreterOptions options = new XppInterpreter.Interpreter.XppInterpreterOptions();
        options.MaxLoopIterations = parameters.MaxLoopIteratations > 0 ? parameters.MaxLoopIteratations : 100000;
        options.MaxInstructions = parameters.MaxInstructions > 0 ? parameters.MaxInstructions : 1000000;
        options.MaxExecutionMilliseconds = parameters.MaxExecutionMilliseconds > 0 ? parameters.MaxExecutionMilliseconds : 300000;
        XppInterpreter.Interpreter.XppInterpreter interpreter = new XppInterpreter.Interpreter.XppInterpreter(proxy, options);

        XppInterpreter.Interpreter.InterpreterResult interpreterResult = interpreter.Interpret(byteCode, _context, false);

        if (_context.Stack.Count == 0)
        {
            return "<executed>";
        }

        return _context.Stack.Pop();
    }
    else
    {
        MXTXppInterpreterCodeEditorParseExceptionCollection collection = new MXTXppInterpreterCodeEditorParseExceptionCollection();

        System.Collections.IEnumerator enumerator = result.Errors.GetEnumerator();

        while (enumerator.MoveNext())
        {
            XppInterpreter.Parser.ParseError err = enumerator.Current;

            throw error(err.Message);
        }

        throw error("An error occurred while evaluating the expression.");
    }
}

/// <summary>
/// Executes the given AST as a Program
/// </summary>
/// <param name = "_program">Program AST</param>
/// <param name = "_debugger">Debugger</param>
/// <param name = "_parameters">Configuration</param>
/// <param name = "_dependencies">Dependency scripts</param>
public static void executeProgram(
    XppInterpreter.Parser.Program               _program, 
    XppInterpreter.Interpreter.Debug.IDebugger _debugger    = null, 
    MXTXppInterpreterParameters                _parameters  = MXTXppInterpreterParameters::find(),
    XppInterpreter.Interpreter.XppInterpreterDependencyCollection _dependencies = null)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();

    // Setup options
    XppInterpreter.Interpreter.XppInterpreterOptions options = new XppInterpreter.Interpreter.XppInterpreterOptions();
    options.EmitGlobalTtsAbort = _parameters.EmitGlobalTtsAbort;
    options.MaxLoopIterations = _parameters.MaxLoopIteratations > 0 ? _parameters.MaxLoopIteratations : 100000;
    options.MaxInstructions = _parameters.MaxInstructions > 0 ? _parameters.MaxInstructions : 1000000;
    options.MaxExecutionMilliseconds = _parameters.MaxExecutionMilliseconds > 0 ? _parameters.MaxExecutionMilliseconds : 300000;

    XppInterpreter.Interpreter.XppInterpreter interpreter = new XppInterpreter.Interpreter.XppInterpreter(proxy, options);
    interpreter.Debugger = _debugger;

    interpreter.Interpret(_program, _dependencies);
}

    /// <summary>
    /// Executes the given source code
    /// </summary>
    /// <param name = "_sourceCode">X++ source code</param>
    /// <param name = "_debugger">Debugger</param>
    /// <param name = "_parameters">Configuration</param>
    /// <param name = "_dependencies">Dependency scripts</param>
    public static void execute(
        str                                         _sourceCode, 
        XppInterpreter.Interpreter.Debug.IDebugger  _debugger = null, 
        MXTXppInterpreterParameters                 _parameters  = MXTXppInterpreterParameters::find(),
        XppInterpreter.Interpreter.XppInterpreterDependencyCollection _dependencies = null)
    {
        MXTXppInterpreterScriptExecutionLog::checkSecurityRights();

        // Create lexer and parser
        XppInterpreter.Parser.ParseResult parseResult = MXTXppInterpreterExecutor::parse(_sourceCode);

        if (parseResult.IsCorrect)
        {
            MXTXppInterpreterScriptExecutionLog::startLog(_sourceCode, _parameters.EmitGlobalTtsAbort);

            MXTXppInterpreterExecutor::executeProgram(parseResult.AST as XppInterpreter.Parser.Program, _debugger, _parameters, _dependencies);
        }

        System.Collections.IEnumerator errorEnumerator = parseResult.Errors.GetEnumerator();

        if (errorEnumerator.MoveNext())
        {
            XppInterpreter.Parser.ParseError parseError = errorEnumerator.Current;
            throw error(parseError.Message);
        }
	}

/// <summary>
/// Executes a script in batch
/// </summary>
/// <param name = "_script">A record of <c>MXTXppInterpreterScript</c></param>
public static void executeScriptInBatch(MXTXppInterpreterScript _script)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();
    Args args = new Args();
    args.record(_script);

    MXTXppInterpreterBatchController::main(args);
}

/// <summary>
/// Converts Stopwatch ticks to microseconds without relying on wall-clock time.
/// </summary>
public static int64 elapsedMicroseconds(System.Diagnostics.Stopwatch _stopwatch)
{
    return (_stopwatch.ElapsedTicks * 1000000) div System.Diagnostics.Stopwatch::Frequency;
}

/// <summary>
/// Compiles an already-validated module plus its pinned dependency programs.
/// </summary>
public static XppInterpreter.Interpreter.Bytecode.ByteCode compileModule(
    XppInterpreter.Parser.Program _program,
    XppInterpreter.Interpreter.XppInterpreterDependencyCollection _dependencies)
{
    XppInterpreter.Interpreter.XppInterpreter interpreter =
        new XppInterpreter.Interpreter.XppInterpreter(
            proxy,
            MXTXppInterpreterExecutor::newFastExecutionOptions());
    return interpreter.Compile(_program, _dependencies);
}

/// <summary>
/// Executes resident bytecode in an interpreter-owned rollback scope.
/// Used by the versioned module registry after a cache hit or compilation.
/// </summary>
public static void executeCompiledFast(
    XppInterpreter.Interpreter.Bytecode.ByteCode _byteCode,
    MXTXppInterpreterExecutionResponse _response)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();
    if (!_byteCode || !_response)
    {
        throw error('Compiled bytecode and an execution response are required.');
    }
    if (appl.ttsLevel() != 0)
    {
        throw error('Compiled module execution requires TTS level zero.');
    }

    int firstInfologLine = infologLine() + 1;
    boolean transactionStarted;
    try
    {
        XppInterpreter.Interpreter.XppInterpreter interpreter =
            new XppInterpreter.Interpreter.XppInterpreter(
                proxy,
                MXTXppInterpreterExecutor::newFastExecutionOptions());

        ttsbegin;
        transactionStarted = true;
        System.Diagnostics.Stopwatch executeWatch = System.Diagnostics.Stopwatch::StartNew();
        interpreter.Interpret(
            _byteCode,
            null,
            true,
            XppInterpreter.Interpreter.Debug.DebugAction::None);
        executeWatch.Stop();
        _response.parmExecuteMicroseconds(
            MXTXppInterpreterExecutor::elapsedMicroseconds(executeWatch));

        ttsabort;
        transactionStarted = false;
        _response.parmRolledBack(true);
        _response.parmSuccess(true);
    }
    catch (Exception::CLRError)
    {
        if (transactionStarted || appl.ttsLevel() > 0)
        {
            ttsabort;
            transactionStarted = false;
            _response.parmRolledBack(true);
        }
        System.Exception clrException = CLRInterop::getLastException();
        _response.parmError(clrException ? clrException.ToString() : 'The compiled module raised a CLR error.');
    }
    catch
    {
        if (transactionStarted || appl.ttsLevel() > 0)
        {
            ttsabort;
            transactionStarted = false;
            _response.parmRolledBack(true);
        }
        str errorMessage;
        if (infologLine() >= firstInfologLine)
        {
            errorMessage = MXTXppInterpreterExecutor::fastExecutionInfologText(firstInfologLine);
        }
        _response.parmError(errorMessage ? errorMessage : 'The compiled module raised an X++ error.');
    }

    if (transactionStarted || appl.ttsLevel() > 0)
    {
        ttsabort;
        _response.parmRolledBack(true);
    }
    if (infologLine() >= firstInfologLine)
    {
        _response.parmOutput(MXTXppInterpreterExecutor::fastExecutionInfologText(firstInfologLine));
    }
}

/// <summary>
/// Builds bounded execution options without reading configuration tables. The fast
/// endpoint must remain usable before database synchronization and must not pay for
/// a SQL round trip on every edit. Transaction handling is performed by executeFast.
/// </summary>
private static XppInterpreter.Interpreter.XppInterpreterOptions newFastExecutionOptions()
{
    XppInterpreter.Interpreter.XppInterpreterOptions options = new XppInterpreter.Interpreter.XppInterpreterOptions();

    options.EmitGlobalTtsAbort = false;
    options.MaxLoopIterations = 100000;
    options.MaxInstructions = 1000000;
    options.MaxExecutionMilliseconds = 30000;

    return options;
}

/// <summary>
/// Returns only messages produced by the current fast execution request.
/// </summary>
private static str fastExecutionInfologText(int _firstLine)
{
    str result;
    for (int line = _firstLine; line <= infologLine(); line++)
    {
        result += (result ? "\n" : "") + infolog.text(line);
    }
    return result;
}

/// <summary>
/// Executes source directly in the resident interpreter and always rolls database
/// work back. This is the low-latency edit/run path used by the custom service.
/// </summary>
public static MXTXppInterpreterExecutionResponse executeFast(MXTXppInterpreterExecutionRequest _request)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();

    if (!_request)
    {
        throw error("An interpreter execution request is required.");
    }

    str sourceCode = _request.parmSourceCode();
    if (!sourceCode)
    {
        throw error("SourceCode is required.");
    }

    if (strLen(sourceCode) > 1000000)
    {
        throw error("SourceCode exceeds the 1,000,000 character immediate-execution limit.");
    }

    if (appl.ttsLevel() != 0)
    {
        throw error("Immediate interpreter execution requires TTS level zero.");
    }

    MXTXppInterpreterExecutionResponse response = new MXTXppInterpreterExecutionResponse();
    str requestId = _request.parmRequestId();
    if (!requestId)
    {
        requestId = guid2Str(newGuid());
    }
    response.parmRequestId(requestId);

    int firstInfologLine = infologLine() + 1;
    boolean transactionStarted;
    System.Diagnostics.Stopwatch totalWatch = System.Diagnostics.Stopwatch::StartNew();

    try
    {
        System.Diagnostics.Stopwatch parseWatch = System.Diagnostics.Stopwatch::StartNew();
        XppInterpreter.Parser.ParseResult parseResult = MXTXppInterpreterExecutor::parse(sourceCode);
        parseWatch.Stop();
        response.parmParseMicroseconds(MXTXppInterpreterExecutor::elapsedMicroseconds(parseWatch));

        if (!parseResult.IsCorrect)
        {
            str parseErrors;
            System.Collections.IEnumerator errorEnumerator = parseResult.Errors.GetEnumerator();
            while (errorEnumerator.MoveNext())
            {
                XppInterpreter.Parser.ParseError parseError = errorEnumerator.Current;
                parseErrors += (parseErrors ? "\n" : "") + parseError.Message;
            }

            response.parmError(parseErrors ? parseErrors : "The source did not parse correctly.");
        }
        else
        {
            XppInterpreter.Interpreter.XppInterpreterOptions options = MXTXppInterpreterExecutor::newFastExecutionOptions();
            XppInterpreter.Interpreter.XppInterpreter interpreter = new XppInterpreter.Interpreter.XppInterpreter(proxy, options);

            System.Diagnostics.Stopwatch compileWatch = System.Diagnostics.Stopwatch::StartNew();
            XppInterpreter.Interpreter.Bytecode.ByteCode byteCode = interpreter.Compile(
                parseResult.AST as XppInterpreter.Parser.Program,
                null);
            compileWatch.Stop();
            response.parmCompileMicroseconds(MXTXppInterpreterExecutor::elapsedMicroseconds(compileWatch));
            response.parmInstructionCount(byteCode.Instructions.Count);

            ttsbegin;
            transactionStarted = true;

            System.Diagnostics.Stopwatch executeWatch = System.Diagnostics.Stopwatch::StartNew();
            interpreter.Interpret(
                byteCode,
                null,
                true,
                XppInterpreter.Interpreter.Debug.DebugAction::None);
            executeWatch.Stop();
            response.parmExecuteMicroseconds(MXTXppInterpreterExecutor::elapsedMicroseconds(executeWatch));

            ttsabort;
            transactionStarted = false;
            response.parmRolledBack(true);
            response.parmSuccess(true);
        }
    }
    catch (Exception::CLRError)
    {
        if (transactionStarted || appl.ttsLevel() > 0)
        {
            ttsabort;
            transactionStarted = false;
            response.parmRolledBack(true);
        }

        System.Exception clrException = CLRInterop::getLastException();
        response.parmError(clrException ? clrException.ToString() : "The interpreter raised a CLR error.");
    }
    catch
    {
        if (transactionStarted || appl.ttsLevel() > 0)
        {
            ttsabort;
            transactionStarted = false;
            response.parmRolledBack(true);
        }

        str errorText;
        if (infologLine() >= firstInfologLine)
        {
            errorText = MXTXppInterpreterExecutor::fastExecutionInfologText(firstInfologLine);
        }
        response.parmError(errorText ? errorText : "The interpreter raised an X++ error.");
    }

    if (transactionStarted || appl.ttsLevel() > 0)
    {
        ttsabort;
        response.parmRolledBack(true);
    }

    if (infologLine() >= firstInfologLine)
    {
        response.parmOutput(MXTXppInterpreterExecutor::fastExecutionInfologText(firstInfologLine));
    }

    totalWatch.Stop();
    response.parmTotalMicroseconds(MXTXppInterpreterExecutor::elapsedMicroseconds(totalWatch));
    return response;
}

/// <summary>
/// Runs one notebook cell in its session. Variables, script classes and imports declared by
/// earlier cells of the same session are visible, and the cell's own declarations stay for the
/// cells after it. Nothing is compiled to metadata. The cell's database work is rolled back
/// unless the request sets Commit.
/// </summary>
public static MXTXppInterpreterExecutionResponse executeNotebookCell(MXTXppNotebookCellRequest _request)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();

    if (!_request || !_request.parmSessionId())
    {
        throw error("A notebook SessionId is required.");
    }

    str sourceCode = _request.parmSourceCode();
    if (!sourceCode)
    {
        throw error("SourceCode is required.");
    }

    if (strLen(sourceCode) > 1000000)
    {
        throw error("SourceCode exceeds the 1,000,000 character cell limit.");
    }

    if (appl.ttsLevel() != 0)
    {
        throw error("Notebook cells require TTS level zero.");
    }

    MXTXppInterpreterExecutionResponse response = new MXTXppInterpreterExecutionResponse();
    str requestId = _request.parmRequestId();
    if (!requestId)
    {
        requestId = guid2Str(newGuid());
    }
    response.parmRequestId(requestId);
    response.parmSessionId(_request.parmSessionId());

    XppInterpreter.Interpreter.NotebookSession session = XppInterpreter.Interpreter.NotebookKernel::Open(_request.parmSessionId(), proxy);

    if (!session.Enter(30000))
    {
        response.parmError("The notebook session is still running another cell.");
        return response;
    }

    int firstInfologLine = infologLine() + 1;
    boolean transactionStarted;
    boolean commit = _request.parmCommit();
    System.Diagnostics.Stopwatch totalWatch = System.Diagnostics.Stopwatch::StartNew();

    try
    {
        if (!session.Preprocessor)
        {
            session.Preprocessor = MXTXppInterpreterExecutor::createMacroPreprocessor();
        }

        XppInterpreter.Interpreter.XppInterpreterOptions options = MXTXppInterpreterExecutor::newFastExecutionOptions();
        XppInterpreter.Interpreter.Bytecode.ByteCode byteCode = session.CompileCell(sourceCode, proxy, options);
        response.parmParseMicroseconds(session.LastParseMicroseconds);
        response.parmCompileMicroseconds(session.LastCompileMicroseconds);
        response.parmCacheHit(session.LastCompileCached);
        response.parmCellNumber(session.CellCount);

        if (!byteCode)
        {
            response.parmError(session.LastError ? session.LastError : "The cell did not parse correctly.");
        }
        else
        {
            response.parmInstructionCount(byteCode.Instructions.Count);
            XppInterpreter.Interpreter.XppInterpreter interpreter = new XppInterpreter.Interpreter.XppInterpreter(proxy, options);

            ttsbegin;
            transactionStarted = true;

            System.Diagnostics.Stopwatch executeWatch = System.Diagnostics.Stopwatch::StartNew();
            interpreter.Interpret(
                byteCode,
                session.CreateContext(byteCode, proxy),
                true,
                XppInterpreter.Interpreter.Debug.DebugAction::None);
            executeWatch.Stop();
            response.parmExecuteMicroseconds(MXTXppInterpreterExecutor::elapsedMicroseconds(executeWatch));

            if (commit)
            {
                ttscommit;
            }
            else
            {
                ttsabort;
                response.parmRolledBack(true);
            }

            transactionStarted = false;
            response.parmSuccess(true);
        }
    }
    catch (Exception::CLRError)
    {
        if (transactionStarted || appl.ttsLevel() > 0)
        {
            ttsabort;
            transactionStarted = false;
            response.parmRolledBack(true);
        }

        System.Exception clrException = CLRInterop::getLastException();
        response.parmError(clrException ? clrException.ToString() : "The cell raised a CLR error.");
    }
    catch
    {
        if (transactionStarted || appl.ttsLevel() > 0)
        {
            ttsabort;
            transactionStarted = false;
            response.parmRolledBack(true);
        }

        str errorText;
        if (infologLine() >= firstInfologLine)
        {
            errorText = MXTXppInterpreterExecutor::fastExecutionInfologText(firstInfologLine);
        }
        response.parmError(errorText ? errorText : "The cell raised an X++ error.");
    }

    if (transactionStarted || appl.ttsLevel() > 0)
    {
        ttsabort;
        response.parmRolledBack(true);
    }

    response.parmVariables(session.DescribeVariables());
    session.Exit();

    if (infologLine() >= firstInfologLine)
    {
        response.parmOutput(MXTXppInterpreterExecutor::fastExecutionInfologText(firstInfologLine));
    }

    totalWatch.Stop();
    response.parmTotalMicroseconds(MXTXppInterpreterExecutor::elapsedMicroseconds(totalWatch));
    return response;
}

/// <summary>
/// Drops a notebook session with all its variables, classes and imports.
/// </summary>
public static MXTXppInterpreterExecutionResponse resetNotebook(MXTXppNotebookCellRequest _request)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();

    if (!_request || !_request.parmSessionId())
    {
        throw error("A notebook SessionId is required.");
    }

    MXTXppInterpreterExecutionResponse response = new MXTXppInterpreterExecutionResponse();
    response.parmSessionId(_request.parmSessionId());
    response.parmRequestId(_request.parmRequestId());
    XppInterpreter.Interpreter.NotebookKernel::Close(_request.parmSessionId());
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// Clears the current infolog
/// </summary>
private static void clearCurrentInfolog()
{
    infolog.clear();
}
